		private void FieldWaza(global::Pml.WazaNo fieldWazaNo, global::Dpr.UI.PokemonPartyItem partyItem, int selectIndex) {
			PokemonParam pokemonParam = partyItem.param.pokemonParam;
			// onFieldWaza is read twice (null test @019fa564, call @019fa588)
			if (UIManager.onFieldWaza != null && UIManager.onFieldWaza(new UIManager.FieldWazaParam { wazaNo = fieldWazaNo, pokemon = pokemonParam }) != UIManager.FieldUseResult.Available)
			{
				switch (fieldWazaNo)
				{
					case WazaNo.TAMAGOUMI:
					case WazaNo.MIRUKUNOMI:
						OpenMessageWindow(new MsgWindowParam
						{
							useMsgFile = MessageManager.Instance.GetMsgFile("dp_options"),
							labelName = "DP_options_604",
							inputEnabled = true,
							inputCloseEnabled = true,
							onFinishedShowAllMessage = () => { },
						});
						return;
					case WazaNo.ANAWOHORU:
					case WazaNo.TEREPOOTO:
					case WazaNo.HURASSYU:
					case WazaNo.AMAIKAORI:
						string fileName;
						string labelName;
						if (!UIManager.Instance.IsFureaiLimit() && FlagWork.GetSysFlag(EvScript.EvWork.SYSFLAG_INDEX.SYS_FLAG_PAIR) && (fieldWazaNo == WazaNo.TEREPOOTO || fieldWazaNo == WazaNo.ANAWOHORU))
						{
							fileName = "dp_scenario3";
							labelName = "DP_menu_msg2_2255_01";
							FieldManager.fwMng.SetPartnerNameToLabel(0);
						}
						else
						{
							fileName = "dp_options";
							labelName = "DP_options_602";
						}
						OpenMessageWindow(new MsgWindowParam
						{
							useMsgFile = MessageManager.Instance.GetMsgFile(fileName),
							labelName = labelName,
							inputEnabled = true,
							inputCloseEnabled = true,
							onFinishedShowAllMessage = () => { },
						});
						return;
					default:
						return;
				}
			}

			switch (fieldWazaNo)
			{
				case WazaNo.TAMAGOUMI:
				case WazaNo.MIRUKUNOMI:
					SelectPokemonByFieldWaza(fieldWazaNo, partyItem);
					break;
				case WazaNo.ANAWOHORU:
				case WazaNo.TEREPOOTO:
				case WazaNo.HURASSYU:
				case WazaNo.AMAIKAORI:
					// PlayerWork static setters inlined (indirect init-flag slots @019fa874 / @019fa8c0)
					PlayerWork.UsedFieldWazaNo = fieldWazaNo;
					PlayerWork.UsedFieldWazaTemotiNo = selectIndex;
					UIManager.Instance.CloseXMenu(onClosed_ => Close(onClosed_, WINDOWID_FIELD));
					break;
			}
		}
		private void OpenBagWindow(global::Dpr.UI.UIBag.ModeType modeType, global::Pml.PokePara.PokemonParam selectPokemonParam) {
			SmartPoint.AssetAssistant.Sequencer.Start(FadeTransition<UIBag>(TransitionFadeFillColor, TransitionFadeDuration, () =>
			{
				Close(_ =>
				{
					UIBag bag = UIManager.Instance.CreateUIWindow<UIBag>(UIWindowID.BAG);
					bag.RegisterCloseOnOpenWindow<PokemonWindow>(TransitionFadeFillColor, TransitionFadeDuration, __ =>
					{
						PokemonWindow window = UIManager.Instance.CreateUIWindow<PokemonWindow>(UIWindowID.POKEMON);
						window.onPreClose = onPreClose;
						window.onClosed = onClosed;
						window.Open(new Param { selectIndex = _party.selectIndex }, bag.instance.windowId);
						window._prevWindowId = _prevWindowId;
					});
					bag.Open(modeType != UIBag.ModeType.Equip ? UIBag.BootType.Pokemon : UIBag.BootType.Default, modeType, selectPokemonParam, -1, true, instance.windowId);
				}, UIWindowID.BAG);
			}));
		}
		private void GiveItem(bool isChain) {
			MsgWindowParam messageParam = new MsgWindowParam
			{
				useMsgFile = MessageManager.Instance.GetMsgFile("ss_pokelist"),
				labelName = "SS_pokelist_09",
				inputEnabled = true,
				inputCloseEnabled = false,
			};
			OpenMessageWindow(messageParam);
			_party.BeginItemSwap((from, to, isEgg, isCancel) =>
			{
				// SetupModelView inlined (its flag 0x4cbc9b8 tested @019fd380)
				SetupModelView(_party.items[_party.selectIndex].param.pokemonParam);
				if (isEgg)
				{
					messageParam = new MsgWindowParam
					{
						useMsgFile = MessageManager.Instance.GetMsgFile("ss_box"),
						labelName = "SS_box_093",
						inputEnabled = true,
						inputCloseEnabled = true,
					};
					messageParam.onFinishedCloseWindow = () =>
					{
						ShowPartyItemName(false);
						_messageWindow = null;
					};
					OpenMessageWindow(messageParam);
					return;
				}

				if (isChain)
				{
					ShowPartyItemName(false);
					CloseMessageWindow();
					if (from != to)
						CheckFormChange(from, () => CheckFormChange(to, () => NextChainItemSwap()));
					else
						NextChainItemSwap();

					return;
				}

				if (from == to)
				{
					CloseMessageWindow();
					ShowPartyItemName(false);
					return;
				}

				ShowPartyItemName(true);
				messageParam = new MsgWindowParam
				{
					useMsgFile = MessageManager.Instance.GetMsgFile("ss_pokelist"),
					labelName = "SS_pokelist_12",
					inputEnabled = true,
					inputCloseEnabled = true,
				};
				messageParam.onFinishedCloseWindow = () =>
				{
					ShowPartyItemName(false);
					_messageWindow = null;
					CheckFormChange(from, () => CheckFormChange(to, () => { }));
				};
				OpenMessageWindow(messageParam);
			});

			void NextChainItemSwap()
			{
				ShowPartyItemName(true);
				_itemSwapSelect = true;
				OpenMessageWindow(new MsgWindowParam
				{
					useMsgFile = MessageManager.Instance.GetMsgFile("ss_pokelist"),
					labelName = "SS_pokelist_08",
					inputEnabled = true,
					inputCloseEnabled = false,
					onFinishedShowAllMessage = () => { },
				});
			}
        }
		private void PokemonSwap() {
			MsgWindowParam messageParam = new MsgWindowParam
			{
				useMsgFile = MessageManager.Instance.GetMsgFile("ss_pokelist"),
				labelName = "SS_pokelist_02",
				inputEnabled = true,
				inputCloseEnabled = false,
				onFinishedCloseWindow = () => { },
			};
			OpenMessageWindow(messageParam);
			_messageWindow.transform.position = _messageWindowRoot.position;
			_party.SetActive(true, false);
			_party.BeginSwap((from, to) =>
			{
				// SetupModelView inlined (its flag 0x4cbc9b8 tested @019fb59c)
				SetupModelView(_party.items[_party.selectIndex].param.pokemonParam);
				_messageWindow.CloseWindow();
				int fromIndex = from.transform.GetSiblingIndex();
				int toIndex = to.transform.GetSiblingIndex();
				if (fromIndex == toIndex)
					return;

				PlayerWork.playerParty.ExchangePosition((byte)fromIndex, (byte)toIndex);
			});
		}
		private void SelectPokemonByFieldWaza(global::Pml.WazaNo wazaNo, global::Dpr.UI.PokemonPartyItem partyItem) {
			OpenMessageWindow(new MsgWindowParam
			{
				useMsgFile = MessageManager.Instance.GetMsgFile("dp_options"),
				labelName = "DP_options_534",
				inputEnabled = true,
				inputCloseEnabled = false,
			});
			_fieldWazaPartyItem = partyItem;
			_fieldWazaNo = wazaNo;
		}
		private void UseFieldWaza(global::Dpr.UI.PokemonPartyItem partyItem) {
			PokemonParam pokemonParam = _fieldWazaPartyItem.param.pokemonParam;
			PokemonParam pokemonParamTo = partyItem.param.pokemonParam;
			UIManager.FieldUseResult? result = UIManager.onFieldWaza?.Invoke(new UIManager.FieldWazaParam { wazaNo = _fieldWazaNo, pokemon = pokemonParam, targetPokemon = pokemonParamTo });
			_isFieldWazaExecuting = result == UIManager.FieldUseResult.Available;
			if (_isFieldWazaExecuting)
			{
				int completeCount = 0;
				int delta = Mathf.Min((int)(pokemonParam.GetMaxHp() / 5), (int)(pokemonParamTo.GetMaxHp() - pokemonParamTo.GetHp()));
				pokemonParam.ReduceNowHp((uint)delta);
				_fieldWazaPartyItem.UpdateHp(OnCompleteUpdateHp);
				pokemonParamTo.RecoverHp((uint)delta);
				Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_BAG_ITEM_RECOVERY, null);
				partyItem.UpdateHp(OnCompleteUpdateHp);

				void OnCompleteUpdateHp()
				{
					completeCount++;
					if (completeCount > 1)
					{
						MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParamTo, true);
						MessageWordSetHelper.SetDigitWord(1, delta);
						OpenMessageWindow(new MsgWindowParam
						{
							useMsgFile = MessageManager.Instance.GetMsgFile("ss_pokelist"),
							labelName = "SS_pokelist_47",
							inputEnabled = true,
							inputCloseEnabled = true,
							onFinishedCloseWindow = () =>
							{
								_fieldWazaNo = WazaNo.NULL;
								_isFieldWazaExecuting = false;
								_party.SetActive(true, false);
							},
						});
					}
				}
			}
			else
			{
				OpenMessageWindow(new MsgWindowParam
				{
					useMsgFile = MessageManager.Instance.GetMsgFile("dp_options"),
					labelName = "DP_options_629",
					inputEnabled = true,
					inputCloseEnabled = true,
					onFinishedCloseWindow = () =>
					{
						SelectPokemonByFieldWaza(_fieldWazaNo, _fieldWazaPartyItem);
						_party.SetActive(true, false);
					},
				});
			}
        }
		private void CheckFormChange(global::Dpr.UI.PokemonPartyItem pokemonPartyItem, global::UnityEngine.Events.UnityAction onComplete = null) {
			// SetInputEnable inlined (flag-less, @019fae70-019fae90)
			SetInputEnable(false);
			_checkFormChangeCount++;
			PokemonParam pokemonParam = pokemonPartyItem.param.pokemonParam;
			ushort nextFormNo = pokemonParam.GetNextFormNoFromHoldItem(pokemonParam.GetItem());
			if (pokemonParam.GetFormNo() != nextFormNo)
			{
				bool isFormChanging = pokemonPartyItem.FormChange(nextFormNo, (RectTransform)transform, pp =>
				{
					if (_party.GetSelectedItem() == pokemonPartyItem)
						SetupModelView(pp);
				}, pp =>
				{
					MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
					OpenMessageWindow(new MsgWindowParam
					{
						useMsgFile = MessageManager.Instance.GetMsgFile("ss_bag"),
						labelName = "SS_bag_146",
						inputEnabled = true,
						inputCloseEnabled = true,
						onFinishedCloseWindow = () =>
						{
							_checkFormChangeCount--;
							SetInputEnable(true);
							onComplete?.Invoke();
						},
					});
				});
				if (isFormChanging)
					return;

				pokemonPartyItem.Setup(pokemonPartyItem.param);
				if (_party.GetSelectedItem() == pokemonPartyItem)
					// LoadModel inlined (its flag 0x4cbc9c4 tested @019fb080)
					_coroutineFormChangeLoadModel = SmartPoint.AssetAssistant.Sequencer.Start(LoadModel());
			}

			_checkFormChangeCount--;
			// SetInputEnable inlined (flag-less, @019faf0c-019faf34)
			SetInputEnable(true);
			onComplete?.Invoke();

			IEnumerator LoadModel()
			{
				GameObject beforeModelObject = UIManager.Instance.modelView.modelParam.gameObject;
				beforeModelObject.SetActive(false);
				float secounds = 0.3f;
				do
				{
					secounds -= Time.deltaTime;
					yield return null;
				}
				while (secounds > 0f);

				// SetupModelView inlined (its flag 0x4cbc9b8 tested @019fe5e4)
				SetupModelView(pokemonPartyItem.param.pokemonParam);
				while (UIManager.Instance.modelView.modelParam != null && UIManager.Instance.modelView.modelParam.gameObject == beforeModelObject)
					yield return null;

				if (beforeModelObject != null)
					beforeModelObject.SetActive(true);

				_coroutineFormChangeLoadModel = null;
			}
        }
		private void SetInputEnable(bool enable) {
			if (enabled && _checkFormChangeCount > 0)
				return;

			_input.inputEnabled = enable;
		}
